"use client";

import { motion } from "framer-motion";
import { cn } from "@/lib/utils";

// ─── Types ──────────────────────────────────────────────────────────────────

interface Testimonial {
  quote: string;
  author: string;
  role: string;
  avatar?: string;
}

interface TestimonialsBlockProps {
  testimonials: Testimonial[];
  className?: string;
  /** Layout style */
  variant?: "grid" | "marquee" | "masonry";
  /** Section heading */
  heading?: string;
  /** Section subtitle */
  subtitle?: string;
}

// ─── Star icon ──────────────────────────────────────────────────────────────

function StarIcon({ className }: { className?: string }) {
  return (
    <svg
      className={className}
      viewBox="0 0 20 20"
      fill="currentColor"
      xmlns="http://www.w3.org/2000/svg"
    >
      <path d="M9.049 2.927c.3-.921 1.603-.921 1.902 0l1.07 3.292a1 1 0 00.95.69h3.462c.969 0 1.371 1.24.588 1.81l-2.8 2.034a1 1 0 00-.364 1.118l1.07 3.292c.3.921-.755 1.688-1.54 1.118l-2.8-2.034a1 1 0 00-1.175 0l-2.8 2.034c-.784.57-1.838-.197-1.539-1.118l1.07-3.292a1 1 0 00-.364-1.118L2.98 8.72c-.783-.57-.38-1.81.588-1.81h3.461a1 1 0 00.951-.69l1.07-3.292z" />
    </svg>
  );
}

// ─── Stars rating ───────────────────────────────────────────────────────────

function StarsRating() {
  return (
    <div className="flex gap-0.5">
      {Array.from({ length: 5 }).map((_, i) => (
        <StarIcon key={i} className="h-4 w-4 text-amber-400" />
      ))}
    </div>
  );
}

// ─── Avatar ─────────────────────────────────────────────────────────────────

function Avatar({ author, avatar }: { author: string; avatar?: string }) {
  const initials = author
    .split(" ")
    .map((n) => n[0])
    .join("")
    .slice(0, 2)
    .toUpperCase();

  if (avatar) {
    return (
      <img
        src={avatar}
        alt={author}
        className="h-10 w-10 rounded-full object-cover ring-2 ring-white/10"
      />
    );
  }

  return (
    <div className="flex h-10 w-10 items-center justify-center rounded-full bg-gradient-to-br from-blue-500 to-cyan-500 text-xs font-bold text-white ring-2 ring-white/10">
      {initials}
    </div>
  );
}

// ─── Testimonial Card ───────────────────────────────────────────────────────

function TestimonialCard({
  testimonial,
  className,
}: {
  testimonial: Testimonial;
  className?: string;
}) {
  return (
    <div
      className={cn(
        "rounded-2xl border border-white/[0.08] bg-white/[0.03] p-6 backdrop-blur-xl transition-all duration-300 hover:border-white/[0.15] hover:bg-white/[0.05]",
        className
      )}
    >
      <StarsRating />
      <p className="mt-4 text-sm leading-relaxed text-zinc-300">
        &ldquo;{testimonial.quote}&rdquo;
      </p>
      <div className="mt-5 flex items-center gap-3">
        <Avatar author={testimonial.author} avatar={testimonial.avatar} />
        <div>
          <p className="text-sm font-semibold text-white">
            {testimonial.author}
          </p>
          <p className="text-xs text-zinc-500">{testimonial.role}</p>
        </div>
      </div>
    </div>
  );
}

// ─── Section Header ─────────────────────────────────────────────────────────

const headingVariants = {
  hidden: { opacity: 0, y: 20 },
  visible: {
    opacity: 1,
    y: 0,
    transition: { duration: 0.5 },
  },
};

function SectionHeader({ heading, subtitle }: { heading?: string; subtitle?: string }) {
  if (!heading && !subtitle) return null;
  return (
    <motion.div className="mb-12 text-center" variants={headingVariants}>
      {heading && (
        <h2 className="text-3xl font-bold tracking-tight text-white sm:text-4xl">{heading}</h2>
      )}
      {subtitle && (
        <p className="mx-auto mt-4 max-w-2xl text-lg leading-relaxed text-zinc-400">{subtitle}</p>
      )}
    </motion.div>
  );
}

// ─── Grid variant ───────────────────────────────────────────────────────────

const containerVariants = {
  hidden: {},
  visible: {
    transition: {
      staggerChildren: 0.1,
    },
  },
};

const cardVariants = {
  hidden: { opacity: 0, y: 24 },
  visible: {
    opacity: 1,
    y: 0,
    transition: { duration: 0.5, ease: [0.25, 0.46, 0.45, 0.94] as [number, number, number, number] },
  },
};

function GridLayout({ testimonials }: { testimonials: Testimonial[] }) {
  return (
    <motion.div
      className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3"
      variants={containerVariants}
      initial="hidden"
      whileInView="visible"
      viewport={{ once: true, amount: 0.1 }}
    >
      {testimonials.map((t, i) => (
        <motion.div key={i} variants={cardVariants}>
          <TestimonialCard testimonial={t} />
        </motion.div>
      ))}
    </motion.div>
  );
}

// ─── Masonry variant ────────────────────────────────────────────────────────

function MasonryLayout({ testimonials }: { testimonials: Testimonial[] }) {
  return (
    <motion.div
      className="columns-1 gap-4 space-y-4 sm:columns-2 lg:columns-3"
      variants={containerVariants}
      initial="hidden"
      whileInView="visible"
      viewport={{ once: true, amount: 0.1 }}
    >
      {testimonials.map((t, i) => (
        <motion.div key={i} variants={cardVariants} className="break-inside-avoid">
          <TestimonialCard testimonial={t} />
        </motion.div>
      ))}
    </motion.div>
  );
}

// ─── Marquee variant ────────────────────────────────────────────────────────

function MarqueeLayout({ testimonials }: { testimonials: Testimonial[] }) {
  const items = [...testimonials, ...testimonials];

  return (
    <div className="relative overflow-hidden">
      <div className="pointer-events-none absolute inset-y-0 left-0 z-10 w-24 bg-gradient-to-r from-black to-transparent" />
      <div className="pointer-events-none absolute inset-y-0 right-0 z-10 w-24 bg-gradient-to-l from-black to-transparent" />

      <div className="flex animate-[marquee-scroll_40s_linear_infinite] gap-4 hover:[animation-play-state:paused]">
        {items.map((t, i) => (
          <div key={i} className="w-[350px] shrink-0">
            <TestimonialCard testimonial={t} />
          </div>
        ))}
      </div>

      <style jsx>{`
        @keyframes marquee-scroll {
          0% {
            transform: translateX(0);
          }
          100% {
            transform: translateX(-50%);
          }
        }
      `}</style>
    </div>
  );
}

// ─── TestimonialsBlock ──────────────────────────────────────────────────────

export function TestimonialsBlock({
  testimonials,
  className,
  variant = "grid",
  heading,
  subtitle,
}: TestimonialsBlockProps) {
  return (
    <motion.div
      className={cn("w-full", className)}
      initial="hidden"
      whileInView="visible"
      viewport={{ once: true, amount: 0.1 }}
    >
      <SectionHeader heading={heading} subtitle={subtitle} />

      {variant === "grid" ? (
        <GridLayout testimonials={testimonials} />
      ) : variant === "masonry" ? (
        <MasonryLayout testimonials={testimonials} />
      ) : (
        <MarqueeLayout testimonials={testimonials} />
      )}
    </motion.div>
  );
}

/*
 * FlexUI Animations
 * Custom CSS keyframes and utility classes required by FlexUI components.
 * This file is auto-installed when you add a component that needs CSS animations.
 */

/* Marquee */
@keyframes marquee {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}
@keyframes marquee-reverse {
  0% { transform: translateX(-50%); }
  100% { transform: translateX(0); }
}
@keyframes marquee-scroll {
  0% { transform: translateX(0); }
  100% { transform: translateX(-100%); }
}
@utility animate-marquee {
  animation: marquee 30s linear infinite;
}
@utility animate-marquee-reverse {
  animation: marquee-reverse 30s linear infinite;
}

/* Shimmer */
@keyframes shimmer {
  0% { transform: translateX(-100%); }
  100% { transform: translateX(100%); }
}
@utility animate-shimmer {
  animation: shimmer 2s linear infinite;
}

/* Typewriter cursor blink */
@keyframes typewriter-blink {
  0%, 100% { opacity: 1; }
  50% { opacity: 0; }
}

/* Gradient text shift */
@keyframes gradient-shift {
  0% { background-position: 0% center; }
  100% { background-position: 200% center; }
}
@utility animate-gradient-shift {
  animation: gradient-shift 3s linear infinite;
}

/* Beam sweep */
@keyframes beam-sweep {
  0% { transform: translateX(-100%) rotate(var(--tw-rotate, 0deg)); opacity: 0; }
  10% { opacity: 1; }
  90% { opacity: 1; }
  100% { transform: translateX(200%) rotate(var(--tw-rotate, 0deg)); opacity: 0; }
}
@utility animate-beam-sweep {
  animation: beam-sweep 8s linear infinite;
}

/* Star twinkle */
@keyframes star-twinkle {
  0%, 100% { opacity: 0.3; }
  50% { opacity: 1; }
}
@utility animate-star-twinkle {
  animation: star-twinkle 3s ease-in-out infinite;
}

/* Mesh gradient blobs */
@keyframes mesh-blob-1 {
  0% { transform: translate(-50%, -50%) translate(0, 0); }
  100% { transform: translate(-50%, -50%) translate(80px, 60px); }
}
@keyframes mesh-blob-2 {
  0% { transform: translate(-50%, -50%) translate(0, 0); }
  100% { transform: translate(-50%, -50%) translate(-60px, 80px); }
}
@keyframes mesh-blob-3 {
  0% { transform: translate(-50%, -50%) translate(0, 0); }
  100% { transform: translate(-50%, -50%) translate(70px, -50px); }
}
@keyframes mesh-blob-4 {
  0% { transform: translate(-50%, -50%) translate(0, 0); }
  100% { transform: translate(-50%, -50%) translate(-50px, -70px); }
}

/* Wavy background drift */
@keyframes wave-drift {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

/* Aurora background shift */
@keyframes aurora-shift {
  0% { transform: translate(0%, 0%) rotate(0deg) scale(1); }
  25% { transform: translate(10%, -15%) rotate(5deg) scale(1.05); }
  50% { transform: translate(-5%, 10%) rotate(-3deg) scale(0.95); }
  75% { transform: translate(-10%, -5%) rotate(4deg) scale(1.02); }
  100% { transform: translate(0%, 0%) rotate(0deg) scale(1); }
}
@utility animate-aurora-shift {
  animation: aurora-shift 8s ease-in-out infinite;
}

/* Particle drift */
@keyframes particle-drift {
  0% { transform: translateY(0px) translateX(0px); opacity: 0; }
  10% { opacity: 1; }
  90% { opacity: 1; }
  100% { transform: translateY(-60px) translateX(20px); opacity: 0; }
}
@utility animate-particle-drift {
  animation: particle-drift 6s ease-in-out infinite;
}

/* Glow button pulse */
@keyframes glow-pulse {
  0%, 100% { box-shadow: 0 0 20px var(--glow-color), 0 0 60px var(--glow-color-soft); }
  50% { box-shadow: 0 0 30px var(--glow-color-intense), 0 0 80px var(--glow-color); }
}

/* Ripple button expand */
@keyframes ripple-expand {
  0% { transform: scale(0); opacity: 1; }
  100% { transform: scale(1); opacity: 0; }
}

/* Gradient border rotation */
@keyframes border-rotate {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}

/* Disintegration particle */
@keyframes disintegrate-particle {
  0% { opacity: 1; transform: translate(0, 0) rotate(0deg) scale(1); }
  100% { opacity: 0; transform: translate(var(--dx), var(--dy)) rotate(var(--rot)) scale(0); }
}

/* Confetti burst */
@keyframes confetti-burst {
  0% { transform: translate(0, 0) rotate(0deg); opacity: 1; }
  100% { transform: translate(var(--confetti-tx), var(--confetti-ty)) rotate(var(--confetti-rot)); opacity: 0; }
}

/* Animated beam travel */
@keyframes beam-travel {
  0% { stroke-dashoffset: 2060; }
  100% { stroke-dashoffset: 0; }
}
@utility animate-beam-travel {
  animation: beam-travel 3s linear infinite;
}

/* Orbit animations */
@keyframes orbit-cw {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}
@keyframes orbit-ccw {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(-360deg); }
}
@utility animate-orbit-cw {
  animation: orbit-cw 20s linear infinite;
}
@utility animate-orbit-ccw {
  animation: orbit-ccw 20s linear infinite;
}

/* Smoke divider */
@keyframes smoke-drift {
  0% { transform: translateX(-200px) translateY(0px); }
  100% { transform: translateX(calc(100vw + 200px)) translateY(0px); }
}
@keyframes smoke-float {
  0%, 100% { transform: translateY(0px); }
  50% { transform: translateY(-8px); }
}

/* Glitch flicker */
@keyframes glitch-flicker {
  0% { opacity: 1; }
  50% { opacity: 0.6; }
  100% { opacity: 1; }
}

/* Retro grid scroll */
@keyframes retro-grid-scroll {
  0% { background-position: 0 0; }
  100% { background-position: 0 40px; }
}

/* Neon pulse glow */
@keyframes neon-pulse {
  0%, 100% { filter: brightness(1); }
  50% { filter: brightness(1.15); }
}
.neon-pulse {
  animation: neon-pulse 3s ease-in-out infinite;
}

/* Pulse ring (pulse-button) */
@keyframes pulse-ring {
  0% { transform: scale(1); opacity: 0.6; }
  100% { transform: scale(1.6); opacity: 0; }
}

/* Orbit spin (orbit-animation) */
@keyframes orbit-spin {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}

/* Glow text (glow-text) */
@keyframes glow-text {
  0% { text-shadow: 0 0 10px var(--glow-color), 0 0 20px var(--glow-color); }
  100% { text-shadow: 0 0 20px var(--glow-color), 0 0 40px var(--glow-color), 0 0 60px var(--glow-color); }
}
